const postReq = network.requests({ method: 'POST', path: '/api/cart' }).slice(-1)[0];
const getReq = network.requests({ method: 'GET', path: '/api/cart' }).slice(-1)[0];
const post = JSON.parse(postReq.responseBody);
const get = JSON.parse(getReq.responseBody);
const productId = JSON.parse(postReq.requestBody).productId;
const beforeItem = get.items.find(item => item.id === productId);
const afterItem = post.items.find(item => item.id === productId);
const beforeQty = beforeItem ? beforeItem.qty : 0;
const afterQty = afterItem ? afterItem.qty : 0;
return String(afterQty - beforeQty);
